   101	    /**
   102	     * The kitchen sets its deposit share, its COD cap and the account customers pay. A new or changed recipient is not
   103	     * offered to customers until staff approve it again.
   104	     */
   105	    @Transactional
   106	    public ProfileView updateProfile(UUID cookId, long expectedVersion, int depositBps, Long codMaxTotalMinor, Recipient r) {
   107	        UUID kitchen = ownKitchen(cookId);
   108	        if (depositBps < 0 || depositBps > 10_000) {
   109	            throw invalid("depositBps", "RANGE_0_10000");
   110	        }
   111	        if (codMaxTotalMinor != null && codMaxTotalMinor < 0) {
   112	            throw invalid("codMaxTotalMinor", "NOT_NEGATIVE");
   113	        }
   114	        if (depositBps > 0 && r == null) {
   115	            throw invalid("recipient", "REQUIRED_FOR_DEPOSIT");
   116	        }
   117	        if (r != null && (r.method() == null || !Set.of("INSTAPAY", "MOBILE_WALLET", "BANK_TRANSFER").contains(r.method())
   118	                || r.identifier() == null || r.identifier().strip().length() < 3 || r.identifier().strip().length() > 64
   119	                || r.name() == null || r.name().strip().length() < 2 || r.name().strip().length() > 80)) {
   120	            throw invalid("recipient", "INVALID_RECIPIENT");
   121	        }
   122	        ProfileView current = profileView(kitchen);
   123	        if (current.version() != expectedVersion) {
   124	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
   125	        }
   126	        Recipient next = r == null ? null : new Recipient(r.method(), r.identifier().strip(), r.name().strip());
   127	        boolean sameRecipient = java.util.Objects.equals(next, current.recipient());
   128	        String status = sameRecipient && next != null ? current.recipientStatus() : "NONE";
   129	        int n = jdbc.update("""
   130	                INSERT INTO kitchen_payment_profile (kitchen_id, deposit_bps, cod_max_total_minor, recipient_method, recipient_identifier, recipient_name,
   131	                                                     recipient_status, version)
   132	                VALUES (?, ?, ?, ?, ?, ?, 'NONE', 1)
   133	                ON CONFLICT (kitchen_id) DO UPDATE SET deposit_bps = EXCLUDED.deposit_bps, cod_max_total_minor = EXCLUDED.cod_max_total_minor,
   134	                    recipient_method = EXCLUDED.recipient_method, recipient_identifier = EXCLUDED.recipient_identifier,
   135	                    recipient_name = EXCLUDED.recipient_name, recipient_status = ?,
   136	                    approved_by = CASE WHEN ? = 'APPROVED' THEN kitchen_payment_profile.approved_by END,
   137	                    approved_at = CASE WHEN ? = 'APPROVED' THEN kitchen_payment_profile.approved_at END,
   138	                    version = kitchen_payment_profile.version + 1
   139	                WHERE kitchen_payment_profile.version = ?""",
   140	                kitchen, depositBps, codMaxTotalMinor, next == null ? null : next.method(), next == null ? null : next.identifier(),
   141	                next == null ? null : next.name(), status, status, status, expectedVersion);
   142	        if (n != 1) {
   143	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
   144	        }
   145	        audit.record(new AuditLog.Entry(cookId, "payment.profile_update", null, "kitchen", kitchen.toString(), AuditLog.Outcome.ALLOWED, null,
   146	                requestId(), Map.of("depositBps", depositBps, "recipientChanged", !sameRecipient)));
   147	        return profileView(kitchen);
   148	    }
