   165	    /** Staff (finance.verify, recent MFA) approve the recipient after checking it against the approved cook. Audited. */
   166	    @Transactional
   167	    public ProfileView approveRecipient(UUID staffId, UUID kitchenId, long expectedVersion, String reason) {
   168	        if (reason == null || reason.strip().length() < 10 || reason.strip().length() > 500) {
   169	            throw invalid("reason", "LENGTH_10_500");
   170	        }
   171	        if (kitchens.ownedBy(staffId).map(KitchenDirectory.KitchenStatus::kitchenId).filter(kitchenId::equals).isPresent()) {
   172	            throw new ApiException(ErrorCode.FORBIDDEN, "cannot approve your own kitchen's recipient");
   173	        }
   174	        ProfileView current = profileView(kitchenId);
   175	        if (current.recipient() == null || current.version() == 0) {
   176	            throw new ApiException(ErrorCode.STATE_CONFLICT, "no recipient to approve", List.of(new FieldError("recipient", "MISSING")));
   177	        }
   178	        int n = jdbc.update("""
   179	                UPDATE kitchen_payment_profile SET recipient_status = 'APPROVED', approved_by = ?, approved_at = ?, version = version + 1
   180	                WHERE kitchen_id = ? AND version = ?""", staffId, Timestamp.from(clock.instant()), kitchenId, expectedVersion);
   181	        if (n != 1) {
   182	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment profile changed");
   183	        }
   184	        audit.record(new AuditLog.Entry(staffId, "payment.recipient_approve", "finance.verify", "kitchen", kitchenId.toString(),
   185	                AuditLog.Outcome.ALLOWED, reason.strip(), requestId(), Map.of("method", current.recipient().method())));
   186	        return profileView(kitchenId);
   187	    }
