   190	    /** The kitchen's current terms; {@code lock} takes a share lock so a change serializes with a placement (as in D13). */
   191	    Profile profile(UUID kitchenId, boolean lock) {
   192	        return jdbc.query("""
   193	                SELECT deposit_bps, cod_max_total_minor, recipient_method, recipient_identifier, recipient_name, recipient_status
   194	                FROM kitchen_payment_profile WHERE kitchen_id = ?""" + (lock ? " FOR SHARE" : ""), rs -> {
   195	            if (!rs.next()) {
   196	                return new Profile(0, null, null);
   197	            }
   198	            Recipient r = "APPROVED".equals(rs.getString(6))
   199	                    ? new Recipient(rs.getString(3), rs.getString(4), rs.getString(5)) : null;
   200	            return new Profile(rs.getInt(1), (Long) rs.getObject(2), r);
   201	        }, kitchenId);
   202	    }
