   204	    /** Server-derived terms for a quote: integer EGP, deposit rounded half up, the rest due at hand-over. */
   205	    Terms terms(Profile p, Method method, long totalMinor) {
   206	        if (method == Method.COD) {
   207	            if (p.codMaxTotalMinor() != null && totalMinor > p.codMaxTotalMinor()) {
   208	                throw invalid("paymentMethod", "COD_NOT_ELIGIBLE");
   209	            }
   210	            return new Terms("COD", 0, egp(0), egp(totalMinor), null);
   211	        }
   212	        if (p.depositBps() == 0 || p.recipient() == null) {
   213	            throw invalid("paymentMethod", "DEPOSIT_NOT_OFFERED");
   214	        }
   215	        long deposit = Math.max(1, Math.floorDiv(Math.addExact(Math.multiplyExact(totalMinor, (long) p.depositBps()), 5_000L), 10_000L));
   216	        return new Terms("DEPOSIT", p.depositBps(), egp(deposit), egp(totalMinor - deposit), p.recipient());
   217	    }
