   219	    /** Writes the immutable payment record of a new order; the deposit is due by the acceptance deadline. */
   220	    void createFor(UUID orderId, UUID customerId, String method, long totalMinor, long depositMinor, Recipient r, Instant acceptBy, Instant now) {
   221	        boolean deposit = "DEPOSIT".equals(method);
   222	        String state = deposit ? "WAITING_FOR_DEPOSIT" : "NOT_REQUIRED";
   223	        jdbc.update("""
   224	                INSERT INTO order_payment (order_id, method, total_minor, deposit_minor, remainder_minor, recipient_method, recipient_identifier,
   225	                                           recipient_name, deposit_expires_at, state, updated_at)
   226	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
   227	                orderId, method, totalMinor, depositMinor, totalMinor - depositMinor, deposit ? r.method() : null, deposit ? r.identifier() : null,
   228	                deposit ? r.name() : null, deposit ? Timestamp.from(acceptBy) : null, state, Timestamp.from(now));
   229	        if (deposit) {
   230	            event(orderId, null, state, "CUSTOMER", customerId, depositMinor, null, null, now);
   231	        }
   232	    }
