   242	    /**
   243	     * The customer says the deposit was sent. Idempotent: a repeated or concurrent report changes nothing more. The
   244	     * report is information for the kitchen, not payment.
   245	     */
   246	    @Transactional
   247	    public PaymentView reportTransfer(UUID customerId, UUID orderId, String reference) {
   248	        Map<String, Object> p = lockForCustomer(customerId, orderId);
   249	        String state = (String) p.get("state");
   250	        if ("CUSTOMER_TRANSFER_REPORTED".equals(state) || "KITCHEN_RECEIPT_REPORTED".equals(state)) {
   251	            return view(orderId).orElseThrow();
   252	        }
   253	        if (!"WAITING_FOR_DEPOSIT".equals(state)) {
   254	            throw new ApiException(ErrorCode.STATE_CONFLICT, "no deposit is waiting", List.of(new FieldError("payment", "NO_DEPOSIT_WAITING")));
   255	        }
   256	        move(orderId, state, "CUSTOMER_TRANSFER_REPORTED", (Long) p.get("version"), "CUSTOMER", customerId, null, reference, null);
   257	        return view(orderId).orElseThrow();
   258	    }
