   260	    /**
   261	     * The kitchen reports that the deposit arrived in its own account. Recorded as the kitchen's statement, not as a
   262	     * bank confirmation. The amount must equal the deposit; a different amount or "not received" is MB-052.
   263	     */
   264	    @Transactional
   265	    public PaymentView kitchenReceipt(UUID cookId, UUID orderId, long expectedVersion, long amountMinor, String reference) {
   266	        UUID kitchen = ownKitchen(cookId);
   267	        Map<String, Object> p = jdbc.queryForList("""
   268	                SELECT p.state, p.version, p.deposit_minor, o.state AS order_state FROM order_payment p JOIN customer_order o ON o.id = p.order_id
   269	                WHERE p.order_id = ? AND o.kitchen_id = ? FOR UPDATE OF p""", orderId, kitchen).stream().findFirst()
   270	                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
   271	        String state = (String) p.get("state");
   272	        if (ENDED.contains((String) p.get("order_state"))) {
   273	            throw new ApiException(ErrorCode.STATE_CONFLICT, "order ended; report a refund instead", List.of(new FieldError("payment", "ORDER_ENDED")));
   274	        }
   275	        if (!Set.of("WAITING_FOR_DEPOSIT", "CUSTOMER_TRANSFER_REPORTED", "DISPUTED").contains(state)) {
   276	            throw new ApiException(ErrorCode.STATE_CONFLICT, "no deposit is waiting", List.of(new FieldError("payment", "NO_DEPOSIT_WAITING")));
   277	        }
   278	        if ((Long) p.get("version") != expectedVersion) {
   279	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment changed");
   280	        }
   281	        if (amountMinor != (Long) p.get("deposit_minor")) {
   282	            throw invalid("amountMinor", "DOES_NOT_MATCH_DEPOSIT");
   283	        }
   284	        move(orderId, state, "KITCHEN_RECEIPT_REPORTED", expectedVersion, "COOK", cookId, amountMinor, reference, null);
   285	        return view(orderId).orElseThrow();
   286	    }
