   288	    /** The kitchen reports that nothing arrived, or a different amount (TC-161). Processing pauses; ops see it in their queue. */
   289	    @Transactional
   290	    public PaymentView reportProblem(UUID cookId, UUID orderId, long expectedVersion, Problem kind, Long amountSeen, String reference) {
   291	        if (kind == Problem.AMOUNT_MISMATCH && (amountSeen == null || amountSeen < 0)) {
   292	            throw invalid("amountMinor", "REQUIRED_FOR_MISMATCH");
   293	        }
   294	        Map<String, Object> p = lockForKitchen(cookId, orderId);
   295	        String state = (String) p.get("state");
   296	        if (!Set.of("WAITING_FOR_DEPOSIT", "CUSTOMER_TRANSFER_REPORTED", "RECONCILE_PENDING").contains(state)) {
   297	            throw new ApiException(ErrorCode.STATE_CONFLICT, "nothing to dispute", List.of(new FieldError("payment", "NOTHING_TO_DISPUTE")));
   298	        }
   299	        checkVersion(p, expectedVersion);
   300	        move(orderId, state, "DISPUTED", expectedVersion, "COOK", cookId, kind == Problem.AMOUNT_MISMATCH ? amountSeen : null, reference, kind.name());
   301	        return view(orderId).orElseThrow();
   302	    }
