   304	    /** Payments that need ops attention, newest first (finance.verify). */
   305	    public List<QueueItem> queue(String state) {
   306	        if (!Set.of("DISPUTED", "RECONCILE_PENDING", "REFUND_OWED").contains(state)) {
   307	            throw invalid("state", "ALLOWED_DISPUTED|RECONCILE_PENDING|REFUND_OWED");
   308	        }
   309	        return jdbc.query("""
   310	                SELECT p.order_id, o.public_number, o.kitchen_id, o.state, p.state, p.deposit_minor, p.updated_at, p.version,
   311	                       (SELECT e.reason_code FROM payment_event e WHERE e.order_id = p.order_id AND e.reason_code IS NOT NULL
   312	                        ORDER BY e.occurred_at DESC LIMIT 1)
   313	                FROM order_payment p JOIN customer_order o ON o.id = p.order_id WHERE p.state = ? ORDER BY p.updated_at DESC LIMIT 100""",
   314	                (rs, n) -> new QueueItem(rs.getObject(1, UUID.class), rs.getString(2), rs.getObject(3, UUID.class), rs.getString(4), rs.getString(5),
   315	                        egp(rs.getLong(6)), rs.getString(9), rs.getTimestamp(7).toInstant(), rs.getLong(8)), state);
   316	    }
