   318	    /**
   319	     * Staff decide on an ended order's open payment, with a reason (audited): the kitchen owes a refund, or the matter
   320	     * is closed without funds. There is no decision that marks money as received.
   321	     */
   322	    @Transactional
   323	    public PaymentView decide(UUID staffId, UUID orderId, long expectedVersion, Decision outcome, String reason) {
   324	        if (reason == null || reason.strip().length() < 10 || reason.strip().length() > 500) {
   325	            throw invalid("reason", "LENGTH_10_500");
   326	        }
   327	        Map<String, Object> p = jdbc.queryForList("""
   328	                SELECT p.state, p.version, o.state AS order_state FROM order_payment p JOIN customer_order o ON o.id = p.order_id
   329	                WHERE p.order_id = ? FOR UPDATE OF p""", orderId).stream().findFirst()
   330	                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
   331	        if (!ENDED.contains((String) p.get("order_state"))) {
   332	            throw new ApiException(ErrorCode.STATE_CONFLICT, "decide once the order has ended", List.of(new FieldError("orderId", "ORDER_ACTIVE")));
   333	        }
   334	        String state = (String) p.get("state");
   335	        if (!Set.of("DISPUTED", "RECONCILE_PENDING").contains(state)) {
   336	            throw new ApiException(ErrorCode.STATE_CONFLICT, "nothing to decide", List.of(new FieldError("payment", "NOTHING_TO_DECIDE")));
   337	        }
   338	        checkVersion(p, expectedVersion);
   339	        move(orderId, state, outcome.name(), expectedVersion, "STAFF", staffId, null, null, outcome.name());
   340	        audit.record(new AuditLog.Entry(staffId, "payment.decision", "finance.verify", "order", orderId.toString(), AuditLog.Outcome.ALLOWED,
   341	                reason.strip(), requestId(), Map.of("outcome", outcome.name(), "from", state)));
   342	        return view(orderId).orElseThrow();
   343	    }
