   388	    /**
   389	     * The order ended without fulfilment (expired, rejected or cancelled). A deposit nobody reported expires; once a
   390	     * transfer was reported by either side, the payment needs reconciliation (refund or confirmation that nothing
   391	     * arrived), never a silent close (TC-160).
   392	     */
   393	    void orderClosed(UUID orderId, String actorType, UUID actorId, String reasonCode) {
   394	        Map<String, Object> p = jdbc.queryForList("SELECT state, version FROM order_payment WHERE order_id = ? FOR UPDATE", orderId).stream()
   395	                .findFirst().orElse(null);
   396	        if (p == null) {
   397	            return;
   398	        }
   399	        String state = (String) p.get("state");
   400	        String to = "WAITING_FOR_DEPOSIT".equals(state) ? "EXPIRED" : AFTER_TRANSFER.contains(state) ? "RECONCILE_PENDING" : null;
   401	        if (to != null) {
   402	            move(orderId, state, to, (Long) p.get("version"), actorType, actorId, null, null, reasonCode);
   403	        }
   404	    }
