   406	    private Map<String, Object> lockForCustomer(UUID customerId, UUID orderId) {
   407	        return jdbc.queryForList("""
   408	                SELECT p.state, p.version FROM order_payment p JOIN customer_order o ON o.id = p.order_id
   409	                WHERE p.order_id = ? AND o.customer_id = ? FOR UPDATE OF p""", orderId, customerId).stream().findFirst()
   410	                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
   411	    }
