   413	    private void move(UUID orderId, String from, String to, long version, String actorType, UUID actorId, Long amount, String reference,
   414	                      String reasonCode) {
   415	        Instant now = clock.instant();
   416	        int updated = jdbc.update("UPDATE order_payment SET state = ?, version = version + 1, updated_at = ? WHERE order_id = ? AND version = ? AND state = ?",
   417	                to, Timestamp.from(now), orderId, version, from);
   418	        if (updated != 1) {
   419	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "payment changed concurrently");
   420	        }
   421	        event(orderId, from, to, actorType, actorId, amount, reference, reasonCode, now);
   422	        if (NEEDS_CASE.contains(to)) {
   423	            cases.openPaymentCase(orderId, to);
   424	        }
   425	    }
   426	
   427	    /** Payment states that need a human: staff own them through one open PAYMENT support case per order (MB-052). */
   428	    static final Set<String> NEEDS_CASE = Set.of("DISPUTED", "RECONCILE_PENDING", "REFUND_OWED");
   429	
   430	    private void event(UUID orderId, String from, String to, String actorType, UUID actorId, Long amount, String reference, String reasonCode,
   431	                       Instant at) {
   432	        jdbc.update("""
   433	                INSERT INTO payment_event (id, order_id, from_state, to_state, actor_type, actor_id, amount_minor, reference, reason_code, request_id,
   434	                                           occurred_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
   435	                UUID.randomUUID(), orderId, from, to, actorType, actorId, amount, reference == null || reference.isBlank() ? null : reference.strip(),
   436	                reasonCode, org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY), Timestamp.from(at));
   437	        if (NOTIFIED.contains(to)) {
   438	            // MB-052 follow-up: the other party hears about it (in-app; channels per O07), in the same transaction.
   439	            jdbc.update("""
   440	                    INSERT INTO outbox_event (id, aggregate_type, aggregate_id, event_type, payload, available_at, created_at, request_id)
   441	                    VALUES (?, 'order', ?, ?, ?::jsonb, ?, ?, ?)""",
   442	                    UUID.randomUUID(), orderId, "PAYMENT_" + to, "{\"orderId\":\"" + orderId + "\",\"state\":\"PAYMENT_" + to + "\"}",
   443	                    Timestamp.from(at), Timestamp.from(at), org.slf4j.MDC.get(com.matbakhy.shared.web.RequestContext.REQUEST_ID_MDC_KEY));
   444	        }
   445	    }
   446	
   447	    /** Payment states the other party is told about: the customer's report goes to the kitchen, the rest to the customer. */
   448	    static final java.util.Set<String> NOTIFIED = java.util.Set.of("CUSTOMER_TRANSFER_REPORTED", "KITCHEN_RECEIPT_REPORTED", "DISPUTED",
   449	            "REFUND_OWED", "REFUNDED");
