    83	    @Transactional
    84	    public UUID customerCancel(UUID customerId, String key, Command c) {
    85	        return idempotency.execute(customerId, "order.customer_cancel", key, c, UUID.class, () -> {
    86	            Order o = lock(c.orderId(), "o.customer_id = ?", customerId);
    87	            guard(o, c);
    88	            if (!o.state().equals("PENDING_ACCEPTANCE")) {
    89	                // After acceptance the customer asks support (BR-028); no unilateral transition.
    90	                throw new ApiException(ErrorCode.STATE_CONFLICT, "customer cannot cancel in " + o.state(),
    91	                        List.of(new FieldError("state", "CANCELLATION_REQUEST_REQUIRED")));
    92	            }
    93	            reason("customer_cancel", c.reasonCode());
    94	            release(o, Stage.RESERVED);
    95	            transition(o, "CANCELLED", "CUSTOMER", customerId, c.reasonCode());
    96	            cash(o, "NOT_DUE");
    97	            return o.id();
    98	        });
    99	    }
