   101	    // ---- cook ----
   102	
   103	    @Transactional(noRollbackFor = ApiException.class)
   104	    public UUID cook(UUID cookId, String key, Command c) {
   105	        KitchenStatus kitchen = kitchens.ownedBy(cookId).orElseThrow(() -> new ApiException(ErrorCode.FORBIDDEN, "not a cook"));
   106	        if (c.action().equals("handover")) {
   107	            // Wrong codes must be counted even though the command fails, so this path keeps its writes on errors.
   108	            return idempotency.execute(cookId, "order.cook_handover", key, c, UUID.class, () -> {
   109	                Order o = lock(c.orderId(), "o.kitchen_id = ?", kitchen.kitchenId());
   110	                guard(o, c);
   111	                handover(o, cookId, c.code());
   112	                return o.id();
   113	            });
   114	        }
   115	        return rollbackOnError(() -> idempotency.execute(cookId, "order.cook_" + c.action(), key, c, UUID.class, () -> {
   116	            Order o = lock(c.orderId(), "o.kitchen_id = ?", kitchen.kitchenId());
   117	            guard(o, c);
   118	            Instant now = clock.instant();
   119	            switch (c.action()) {
   120	                case "accept" -> {
   121	                    require(o, "PENDING_ACCEPTANCE");
   122	                    if (!kitchen.canAcceptOrders()) {
   123	                        throw new ApiException(ErrorCode.KITCHEN_UNAVAILABLE, "kitchen cannot accept orders");
   124	                    }
   125	                    if (!now.isBefore(o.acceptBy())) {
   126	                        throw new ApiException(ErrorCode.STATE_CONFLICT, "acceptance deadline passed",
   127	                                List.of(new FieldError("acceptBy", "DEADLINE_PASSED")));
   128	                    }
   129	                    move(o, Stage.RESERVED, Stage.ALLOCATED, "RESERVED", "ALLOCATED");
   130	                    transition(o, "ACCEPTED", "COOK", cookId, null);
   131	                }
   132	                case "reject" -> {
   133	                    require(o, "PENDING_ACCEPTANCE");
   134	                    reason("reject", c.reasonCode());
   135	                    release(o, Stage.RESERVED);
   136	                    transition(o, "REJECTED", "COOK", cookId, c.reasonCode());
   137	                    cash(o, "NOT_DUE");
   138	                }
   139	                case "prepare" -> {
   140	                    require(o, "ACCEPTED");
   141	                    fulfillable(kitchen);
   142	                    payments.requireReadyForPreparation(o.id());
   143	                    move(o, Stage.ALLOCATED, Stage.CONSUMED, "ALLOCATED", "CONSUMED");
   144	                    transition(o, "PREPARING", "COOK", cookId, null);
   145	                }
   146	                case "ready" -> {
   147	                    require(o, "PREPARING");
   148	                    fulfillable(kitchen);
   149	                    issueChallenge(o);
   150	                    transition(o, "READY", "COOK", cookId, null);
   151	                }
   152	                case "dispatch" -> {
   153	                    require(o, "READY");
   154	                    if (!o.mode().equals("DELIVERY")) {
   155	                        throw wrongMode();
   156	                    }
   157	                    if (c.reference() == null || c.reference().isBlank() || c.reference().length() > 200) {
   158	                        throw invalid("deliveryReference", "REQUIRED");
   159	                    }
   160	                    jdbc.update("UPDATE customer_order SET dispatch_reference = ? WHERE id = ?", c.reference().strip(), o.id());
   161	                    transition(o, "OUT_FOR_DELIVERY", "COOK", cookId, null);
   162	                }
   163	                case "delivery_failure" -> {
   164	                    if (!o.mode().equals("DELIVERY")) {
   165	                        throw wrongMode();
   166	                    }
   167	                    require(o, "OUT_FOR_DELIVERY");
   168	                    reason("delivery_failure", c.reasonCode());
   169	                    transition(o, "DELIVERY_FAILED", "COOK", cookId, c.reasonCode());
   170	                }
   171	                case "cancel" -> {
   172	                    // Only before preparation; afterwards ops handles exceptions (BR-028/BR-029).
   173	                    require(o, "ACCEPTED");
   174	                    reason("cook_cancel", c.reasonCode());
   175	                    release(o, Stage.ALLOCATED);
   176	                    transition(o, "CANCELLED", "COOK", cookId, c.reasonCode());
   177	                    cash(o, "NOT_DUE");
   178	                }
   179	                default -> throw new IllegalArgumentException("unknown action " + c.action());
   180	            }
   181	            return o.id();
   182	        }));
   183	    }
