   187	    @Transactional
   188	    public UUID opsExceptionCancel(UUID staffId, String key, Command c, String requestId) {
   189	        return idempotency.execute(staffId, "order.ops_exception_cancel", key, c, UUID.class, () -> {
   190	            Order o = lock(c.orderId(), "true OR ?::uuid IS NULL", (Object) null);
   191	            guard(o, c);
   192	            if (!o.state().equals("PREPARING") && !o.state().equals("READY")) {
   193	                throw new ApiException(ErrorCode.STATE_CONFLICT, "exception cancel only from PREPARING or READY");
   194	            }
   195	            reason("exception_cancel", c.reasonCode());
   196	            if (c.reference() == null || c.reference().isBlank()) {
   197	                throw invalid("caseId", "REQUIRED");
   198	            }
   199	            // Consumed stock stays consumed; finance reviews the cash obligation manually (BR-029).
   200	            transition(o, "CANCELLED", "STAFF", staffId, c.reasonCode());
   201	            audit.record(new Entry(staffId, "order.exception_cancel", "order.exception_cancel", "order", o.id().toString(), Outcome.ALLOWED,
   202	                    c.note() == null ? c.reasonCode() : c.note(), requestId, Map.of("reasonCode", c.reasonCode(), "caseRef", c.reference())));
   203	            return o.id();
   204	        });
   205	    }
