   207	    @Transactional
   208	    public UUID opsHandoverOverride(UUID staffId, String key, Command c, String requestId) {
   209	        return idempotency.execute(staffId, "order.ops_handover_override", key, c, UUID.class, () -> {
   210	            Order o = lock(c.orderId(), "true OR ?::uuid IS NULL", (Object) null);
   211	            guard(o, c);
   212	            requireHandoverState(o);
   213	            if (c.note() == null || c.note().strip().length() < 10) {
   214	                throw invalid("reason", "MIN_10_CHARS");
   215	            }
   216	            if (c.reference() == null || c.reference().isBlank()) {
   217	                throw invalid("evidenceRef", "REQUIRED");
   218	            }
   219	            jdbc.update("UPDATE handover_challenge SET consumed_at = ? WHERE order_id = ? AND consumed_at IS NULL", Timestamp.from(clock.instant()),
   220	                    o.id());
   221	            transition(o, "COMPLETED", "STAFF", staffId, "HANDOVER_OVERRIDE");
   222	            audit.record(new Entry(staffId, "order.handover_override", "order.handover_override", "order", o.id().toString(), Outcome.ALLOWED,
   223	                    c.note(), requestId, Map.of("evidenceRef", c.reference(), "mode", o.mode())));
   224	            return o.id();
   225	        });
   226	    }
