   230	    /** Due pending orders (server time); each is expired by {@link #expireOne} in its own transaction. */
   231	    public List<UUID> dueForExpiry(int limit) {
   232	        return jdbc.queryForList("SELECT id FROM customer_order WHERE state = 'PENDING_ACCEPTANCE' AND accept_by <= ? ORDER BY accept_by LIMIT ?",
   233	                UUID.class, Timestamp.from(clock.instant()), limit);
   234	    }
