   236	    @Transactional
   237	    public boolean expireOne(UUID orderId) {
   238	        Order o = jdbc.query("""
   239	                SELECT id, customer_id, kitchen_id, slot_id, state, fulfillment_mode, accept_by, version FROM customer_order o
   240	                WHERE id = ? FOR UPDATE""", (rs, n) -> map(rs), orderId).stream().findFirst().orElse(null);
   241	        if (o == null || !o.state().equals("PENDING_ACCEPTANCE") || clock.instant().isBefore(o.acceptBy())) {
   242	            return false;
   243	        }
   244	        release(o, Stage.RESERVED);
   245	        transition(o, "EXPIRED", "SYSTEM", null, "ACCEPTANCE_DEADLINE");
   246	        cash(o, "NOT_DUE");
   247	        return true;
   248	    }
