   252	    private <T> T rollbackOnError(Supplier<T> body) {
   253	        try {
   254	            return body.get();
   255	        } catch (RuntimeException e) {
   256	            org.springframework.transaction.interceptor.TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();
   257	            throw e;
   258	        }
   259	    }
