   261	    private Order lock(UUID orderId, String scope, Object scopeArg) {
   262	        return jdbc.query("SELECT id, customer_id, kitchen_id, slot_id, state, fulfillment_mode, accept_by, version FROM customer_order o "
   263	                + "WHERE o.id = ? AND (" + scope + ") FOR UPDATE", (rs, n) -> map(rs), orderId, scopeArg).stream().findFirst()
   264	                .orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "order not found"));
   265	    }
