   267	    private static Order map(java.sql.ResultSet rs) throws java.sql.SQLException {
   268	        return new Order(rs.getObject("id", UUID.class), rs.getObject("customer_id", UUID.class), rs.getObject("kitchen_id", UUID.class),
   269	                rs.getObject("slot_id", UUID.class), rs.getString("state"), rs.getString("fulfillment_mode"),
   270	                rs.getTimestamp("accept_by").toInstant(), rs.getLong("version"));
   271	    }
