   273	    private static void guard(Order o, Command c) {
   274	        if (c.expectedVersion() == null) {
   275	            throw invalid("expectedVersion", "REQUIRED");
   276	        }
   277	        if (TERMINAL.contains(o.state())) {
   278	            throw new ApiException(ErrorCode.STATE_CONFLICT, "order is terminal: " + o.state(), List.of(new FieldError("state", o.state())));
   279	        }
   280	        if (c.expectedVersion() != o.version()) {
   281	            throw new ApiException(ErrorCode.VERSION_CONFLICT, "stale order version");
   282	        }
   283	    }
