   285	    private static void require(Order o, String state) {
   286	        if (!o.state().equals(state)) {
   287	            throw new ApiException(ErrorCode.STATE_CONFLICT, "expected " + state + " but order is " + o.state(),
   288	                    List.of(new FieldError("state", o.state())));
   289	        }
   290	    }
