   292	    private static void requireHandoverState(Order o) {
   293	        boolean pickupReady = o.mode().equals("PICKUP") && o.state().equals("READY");
   294	        boolean deliveryOut = o.mode().equals("DELIVERY") && o.state().equals("OUT_FOR_DELIVERY");
   295	        if (!pickupReady && !deliveryOut) {
   296	            if (o.mode().equals("DELIVERY") && o.state().equals("READY")) {
