    32	    @Test
    33	    void implemented_registry_entries_and_served_api_routes_are_the_same_set() throws Exception {
    34	        JsonNode registry = json.readTree(Files.readString(Path.of("../../contracts/endpoints.json")));
    35	        Set<String> implemented = new TreeSet<>();
    36	        for (JsonNode e : registry.get("endpoints")) {
    37	            if (e.get("implemented").asBoolean()) {
    38	                implemented.add(e.get("method").asString() + " " + normalize(e.get("path").asString()));
    39	            }
    40	        }
    41	        Set<String> served = new TreeSet<>();
    42	        mappings.getHandlerMethods().forEach((info, handler) -> {
    43	            if (handler.getBeanType().getName().contains("Test")) {
    44	                return; // probe controllers declared by tests
    45	            }
    46	            for (String pattern : info.getPatternValues()) {
    47	                if (pattern.startsWith("/api/")) {
    48	                    info.getMethodsCondition().getMethods().forEach(m -> served.add(m.name() + " " + normalize(pattern)));
    49	                }
    50	            }
    51	        });
    52	        assertThat(served).isEqualTo(implemented);
    53	    }
