    93	        contact.requireVerifiedContact(customerId);
    94	        Policy policy = policies.active();
    95	        if (in.items() == null || in.items().isEmpty() || in.items().size() > MAX_ITEMS) {
    96	            throw invalid("items", "COUNT_1_TO_20");
    97	        }
    98	        Set<UUID> seen = new HashSet<>();
    99	        for (ItemRequest item : in.items()) {
   100	            if (item.mealId() == null || !seen.add(item.mealId())) {
   101	                throw invalid("items", "DUPLICATE_OR_MISSING_MEAL");
   102	            }
   103	            if (item.quantity() < 1 || item.quantity() > policy.maxItemQuantity()) {
   104	                throw invalid("items.quantity", "RANGE_1_TO_" + policy.maxItemQuantity());
   105	            }
   106	        }
   107	        if (in.slotId() == null || in.fulfillmentMode() == null) {
   108	            throw invalid(in.slotId() == null ? "slotId" : "fulfillmentMode", "REQUIRED");
   109	        }
   110	        Instant now = clock.instant();
   111	        Terms t = terms(customerId, in.items(), in.slotId(), in.fulfillmentMode(), in.addressId(), policy, now);
   112	        PaymentService.Method method = in.paymentMethod() == null ? PaymentService.Method.COD : in.paymentMethod();
   113	        PaymentService.Terms pay = payments.terms(payments.profile(t.seller().kitchenId(), false), method, t.total());
   114	
   115	        UUID id = UUID.randomUUID();
   116	        Instant expires = now.plus(Duration.ofSeconds(policy.quoteTtlSeconds()));
   117	        boolean delivery = in.fulfillmentMode() == Mode.DELIVERY;
   118	        jdbc.update("""
   119	                INSERT INTO quote (id, customer_id, kitchen_id, slot_id, fulfillment_mode, address_id, address_version, zone_id, policy_version,
   120	                                   subtotal_minor, delivery_fee_minor, tax_minor, total_minor, accept_by_preview, expires_at, created_at,
   121	                                   payment_method, deposit_bps, deposit_minor, recipient_method, recipient_identifier, recipient_name)
   122	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
   123	                id, customerId, t.seller().kitchenId(), in.slotId(), in.fulfillmentMode().name(), delivery ? t.address().id() : null,
   124	                delivery ? t.address().version() : null, delivery ? t.address().zoneId() : null, policy.version(), t.subtotal(), t.deliveryFee(),
   125	                t.tax(), t.total(), Timestamp.from(t.acceptBy()), Timestamp.from(expires), Timestamp.from(now), pay.method(), pay.depositBps(),
   126	                pay.deposit().amountMinor(), pay.recipient() == null ? null : pay.recipient().method(),
   127	                pay.recipient() == null ? null : pay.recipient().identifier(), pay.recipient() == null ? null : pay.recipient().name());
   128	        List<QuoteLine> lines = new ArrayList<>();
   129	        for (Priced p : t.lines()) {
   130	            jdbc.update("""
   131	                    INSERT INTO quote_item (quote_id, meal_id, meal_revision, quantity, unit_price_minor, line_total_minor)
   132	                    VALUES (?, ?, ?, ?, ?, ?)""", id, p.meal().mealId(), p.meal().revision(), p.quantity(), p.meal().priceMinor(), p.lineTotal());
   133	            String title = english && p.meal().titleEn() != null ? p.meal().titleEn() : p.meal().titleAr();
   134	            lines.add(new QuoteLine(p.meal().mealId(), p.meal().revision(), title, p.quantity(), egp(p.meal().priceMinor()), egp(p.lineTotal())));
   135	        }
   136	        List<String> warnings = new ArrayList<>();
   137	        if (policy.synthetic()) {
   138	            warnings.add("SYNTHETIC_POLICY");
   139	        }
   140	        return new QuoteResponse(id, expires, t.seller().kitchenId(), lines, egp(t.subtotal()), egp(t.deliveryFee()), egp(t.tax()), egp(t.total()),
   141	                policy.cancellationPolicyVersion(), policy.termsVersion(), t.acceptBy(), warnings, pay);
   142	    }
