   145	    @Transactional
   146	    public ValidQuote requireValid(UUID customerId, UUID quoteId) {
   147	        Map<String, Object> q = jdbc.queryForList("SELECT * FROM quote WHERE id = ? AND customer_id = ?", quoteId, customerId).stream()
   148	                .findFirst().orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "quote not found"));
   149	        // D13: lock the active policy and the rows that price this quote before reading them, so a concurrent price, fee or
   150	        // policy change is serialized with the placement: an update that commits first is seen here (stale quote refused);
   151	        // an update that comes later waits until this placement commits (the order keeps its validated price).
   152	        jdbc.queryForList("SELECT version FROM commerce_policy WHERE status = 'ACTIVE' FOR SHARE", Integer.class);
   153	        meals.lockPricing(jdbc.queryForList("SELECT meal_id FROM quote_item WHERE quote_id = ?", UUID.class, quoteId),
   154	                (UUID) q.get("kitchen_id"), (UUID) q.get("zone_id"));
   155	        Instant now = clock.instant();
   156	        Instant expires = ((Timestamp) q.get("expires_at")).toInstant();
   157	        if (!now.isBefore(expires)) {
   158	            throw new ApiException(ErrorCode.QUOTE_EXPIRED, "quote expired", List.of(new FieldError("quoteId", "QUOTE_EXPIRED")));
   159	        }
   160	        contact.requireVerifiedContact(customerId);
   161	        Policy policy = policies.active();
   162	        if (policy.version() != (Integer) q.get("policy_version")) {
   163	            throw changed(ErrorCode.PRICE_CHANGED, "POLICY_CHANGED");
   164	        }
   165	        List<QuotedItem> items = jdbc.query("""
   166	                SELECT meal_id, meal_revision, quantity, unit_price_minor, line_total_minor FROM quote_item WHERE quote_id = ? ORDER BY meal_id""",
   167	                (rs, n) -> new QuotedItem(rs.getObject(1, UUID.class), rs.getInt(2), rs.getInt(3), rs.getLong(4), rs.getLong(5)), quoteId);
   168	        Mode mode = Mode.valueOf((String) q.get("fulfillment_mode"));
   169	        UUID addressId = (UUID) q.get("address_id");
   170	        Terms t = terms(customerId, items.stream().map(i -> new ItemRequest(i.mealId(), i.quantity())).toList(), (UUID) q.get("slot_id"), mode,
   171	                addressId, policy, now);
   172	        for (QuotedItem item : items) {
   173	            Priced current = t.lines().stream().filter(p -> p.meal().mealId().equals(item.mealId())).findFirst().orElseThrow();
   174	            if (current.meal().revision() != item.mealRevision() || current.meal().priceMinor() != item.unitPriceMinor()) {
   175	                throw changed(ErrorCode.PRICE_CHANGED, "MEAL_CHANGED");
   176	            }
   177	        }
   178	        if (addressId != null && (t.address().version() != (Long) q.get("address_version") || !t.address().zoneId().equals(q.get("zone_id")))) {
   179	            throw changed(ErrorCode.STATE_CONFLICT, "ADDRESS_CHANGED");
   180	        }
   181	        if (t.deliveryFee() != (Long) q.get("delivery_fee_minor") || t.total() != (Long) q.get("total_minor")) {
   182	            throw changed(ErrorCode.PRICE_CHANGED, "TOTAL_CHANGED");
   183	        }
   184	        // MB-051: the kitchen's payment terms are part of the quote; a change since quoting needs a new quote (D13 protocol).
   185	        PaymentService.Terms pay;
   186	        try {
   187	            pay = payments.terms(payments.profile(t.seller().kitchenId(), true), PaymentService.Method.valueOf((String) q.get("payment_method")), t.total());
   188	        } catch (ApiException e) {
   189	            throw changed(ErrorCode.PRICE_CHANGED, "PAYMENT_CHANGED");
   190	        }
   191	        if (pay.depositBps() != (Integer) q.get("deposit_bps") || pay.deposit().amountMinor() != (Long) q.get("deposit_minor")
   192	                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().identifier(), q.get("recipient_identifier"))
   193	                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().method(), q.get("recipient_method"))
   194	                || !java.util.Objects.equals(pay.recipient() == null ? null : pay.recipient().name(), q.get("recipient_name"))) {
   195	            throw changed(ErrorCode.PRICE_CHANGED, "PAYMENT_CHANGED");
   196	        }
   197	        return new ValidQuote(quoteId, customerId, t.seller().kitchenId(), (UUID) q.get("slot_id"), mode.name(), addressId,
   198	                (Long) q.get("address_version"), (UUID) q.get("zone_id"), policy.version(), t.subtotal(), t.deliveryFee(), t.tax(), t.total(),
   199	                ((Timestamp) q.get("accept_by_preview")).toInstant(), expires, items, t.acceptBy(), policy.commissionRateBps(),
   200	                policy.cancellationPolicyVersion(), policy.termsVersion(), pay.method(), pay.deposit().amountMinor(),
   201	                pay.recipient() == null ? null : pay.recipient().method(), pay.recipient() == null ? null : pay.recipient().identifier(),
   202	                pay.recipient() == null ? null : pay.recipient().name());
   203	    }
