   206	    private Terms terms(UUID customerId, List<ItemRequest> items, UUID slotId, Mode mode, UUID addressId, Policy policy, Instant now) {
   207	        SlotStatus slot = slots.slot(slotId).orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "slot not found"));
   208	        Seller seller = sellers.byKitchen(slot.kitchenId()).orElseThrow(() -> new ApiException(ErrorCode.NOT_FOUND, "kitchen not found"));
   209	        if (!seller.canSell()) {
   210	            throw new ApiException(ErrorCode.KITCHEN_UNAVAILABLE, "kitchen not selling");
   211	        }
   212	        if (!slot.orderableAt(now)) {
   213	            throw new ApiException(ErrorCode.SLOT_CLOSED, "slot not orderable", List.of(new FieldError("slotId", "SLOT_CLOSED")));
   214	        }
   215	        Instant acceptBy = now.plus(Duration.ofMinutes(policy.acceptanceWindowMinutes()));
   216	        if (slot.cutoffAt().isBefore(acceptBy)) {
   217	            acceptBy = slot.cutoffAt();
   218	        }
   219	        if (Duration.between(now, acceptBy).compareTo(Duration.ofMinutes(policy.minAcceptanceMinutes())) < 0) {
   220	            throw new ApiException(ErrorCode.SLOT_CLOSED, "too close to cutoff", List.of(new FieldError("slotId", "ACCEPTANCE_WINDOW_TOO_SHORT")));
   221	        }
   222	        List<Priced> lines = new ArrayList<>();
   223	        long subtotal = 0;
   224	        int portions = 0;
   225	        for (ItemRequest item : items) {
   226	            PricedMeal meal = meals.current(item.mealId()).filter(PricedMeal::published)
   227	                    .orElseThrow(() -> new ApiException(ErrorCode.STOCK_CHANGED, "meal not available",
   228	                            List.of(new FieldError("items", "MEAL_NOT_AVAILABLE"))));
   229	            if (!meal.kitchenId().equals(slot.kitchenId())) {
   230	                // One cook and one slot per basket (BR-018); never split or convert silently.
   231	                throw invalid("items", "MIXED_KITCHENS_OR_SLOT");
   232	            }
   233	            if (!slot.mealAvailablePortions().containsKey(meal.mealId())) {
   234	                throw invalid("items", "MEAL_NOT_OFFERED_IN_SLOT");
   235	            }
   236	            if (item.quantity() > slot.availableFor(meal.mealId())) {
   237	                throw new ApiException(ErrorCode.STOCK_CHANGED, "not enough portions", List.of(new FieldError("items.quantity", "INSUFFICIENT_PORTIONS")));
   238	            }
   239	            long line = Math.multiplyExact(meal.priceMinor(), (long) item.quantity());
   240	            subtotal = Math.addExact(subtotal, line);
   241	            portions += item.quantity();
   242	            lines.add(new Priced(meal, item.quantity(), line));
   243	        }
   244	        if (portions > slot.availablePortions()) {
   245	            throw new ApiException(ErrorCode.STOCK_CHANGED, "not enough portions in slot", List.of(new FieldError("items.quantity", "INSUFFICIENT_PORTIONS")));
   246	        }
   247	        long fee = 0;
   248	        OwnedAddress address = null;
   249	        if (mode == Mode.PICKUP) {
   250	            if (addressId != null) {
   251	                throw invalid("addressId", "NOT_ALLOWED_FOR_PICKUP");
   252	            }
