   209	    private void changePriceInCurrentTransaction(UUID meal, long price) {
   210	        Integer revision = jdbc.queryForObject("SELECT revision FROM meal WHERE id = ? FOR UPDATE", Integer.class, meal);
   211	        jdbc.update("UPDATE meal SET price_minor = ?, revision = ?, version = version + 1, updated_at = now() WHERE id = ?", price, revision + 1, meal);
   212	        jdbc.update("""
   213	                INSERT INTO meal_revision (meal_id, revision, snapshot, price_minor)
   214	                SELECT meal_id, ?, jsonb_set(snapshot, '{priceMinor}', to_jsonb(?::bigint)), ? FROM meal_revision WHERE meal_id = ? AND revision = ?""",
   215	                revision + 1, price, price, meal, revision);
   216	    }
