    45	    @Override
    46	    // Business failures (ApiException) leave the rollback decision to the caller's transaction, so a caller can keep
    47	    // deliberate writes such as counted failed attempts; any other failure marks the transaction for rollback.
    48	    @Transactional(propagation = Propagation.MANDATORY, noRollbackFor = ApiException.class)
    49	    public <T> T execute(UUID actorId, String command, String idempotencyKey, Object request, Class<T> resultType, Supplier<T> action) {
    50	        if (idempotencyKey == null || !KEY.matcher(idempotencyKey).matches()) {
    51	            throw new ApiException(ErrorCode.MALFORMED_REQUEST, "Idempotency-Key missing or malformed",
    52	                    List.of(new ApiException.FieldError("Idempotency-Key", "REQUIRED")));
    53	        }
    54	        String hash = sha256(json.writeValueAsString(request));
    55	        Timestamp now = Timestamp.from(clock.instant());
    56	        int inserted = jdbc.update("""
    57	                INSERT INTO idempotency_record (actor_id, command, idempotency_key, request_hash, created_at, expires_at)
    58	                VALUES (?, ?, ?, ?, ?, ?) ON CONFLICT DO NOTHING""",
    59	                actorId, command, idempotencyKey, hash, now, Timestamp.from(now.toInstant().plus(RETENTION)));
    60	        if (inserted == 0) {
    61	            List<Map<String, Object>> rows = jdbc.queryForList("""
    62	                    SELECT request_hash, response_snapshot::text AS snapshot FROM idempotency_record
    63	                    WHERE actor_id = ? AND command = ? AND idempotency_key = ? FOR UPDATE""", actorId, command, idempotencyKey);
    64	            if (rows.isEmpty()) {
    65	                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "idempotency record vanished");
    66	            }
    67	            if (!hash.equals(rows.getFirst().get("request_hash"))) {
    68	                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "Idempotency-Key reused with a different request");
    69	            }
    70	            Object snapshot = rows.getFirst().get("snapshot");
    71	            if (snapshot == null) {
    72	                throw new ApiException(ErrorCode.IDEMPOTENCY_CONFLICT, "original request has no stored result");
    73	            }
    74	            return json.readValue(snapshot.toString(), resultType);
    75	        }
    76	        T result;
    77	        try {
    78	            result = action.get();
    79	        } catch (RuntimeException failure) {
    80	            // A failed command stores no outcome, even if the caller's transaction does not roll back. If the database
    81	            // already aborted the transaction the rollback removes the record anyway; the original failure is kept.
    82	            try {
    83	                jdbc.update("DELETE FROM idempotency_record WHERE actor_id = ? AND command = ? AND idempotency_key = ?",
    84	                        actorId, command, idempotencyKey);
    85	            } catch (RuntimeException cleanup) {
    86	                failure.addSuppressed(cleanup);
    87	            }
    88	            throw failure;
    89	        }
    90	        jdbc.update("""
    91	                UPDATE idempotency_record SET result_status = 200, response_snapshot = ?::jsonb
    92	                WHERE actor_id = ? AND command = ? AND idempotency_key = ?""",
    93	                json.writeValueAsString(result), actorId, command, idempotencyKey);
    94	        return result;
    95	    }
